package au.monster.tracker;
import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import java.util.*;

public final class RefundStore {
    private final Store store;public RefundStore(Store store){this.store=store;}
    public record View(List<Refunds.Request> requests,List<Refunds.Observation> observations,List<Refunds.Return> returns,Refunds.State state){}
    private static List<Object> rows(SQLiteDatabase db,String table){List<Object> result=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT body FROM "+table+" ORDER BY rowid",null)){while(c.moveToNext())result.add(Json.parse(c.getString(0)));}return result;}
    public View view(){synchronized(store){Map<String,Object> data=export();var requests=Refunds.requests(data);var observations=Refunds.observations(data);var returns=Refunds.returns(data);var events=store.snapshot().events();Refunds.validate(requests,observations,returns,events);return new View(requests,observations,returns,Refunds.state(requests,observations,events));}}
    public Map<String,Object> export(){synchronized(store){Map<String,Object> result=new LinkedHashMap<>();SQLiteDatabase db=store.database();result.put("requests",rows(db,"refund_requests"));result.put("observations",rows(db,"refund_observations"));result.put("returns",rows(db,"refund_returns"));return result;}}
    private static void insert(SQLiteDatabase db,String table,String id,Map<String,Object> body,ContentValues fields){fields.put("id",id);fields.put("body",Json.write(body));db.insertOrThrow(table,null,fields);}
    private static String existing(SQLiteDatabase db,String table,String id){try(Cursor c=db.rawQuery("SELECT body FROM "+table+" WHERE id=?",new String[]{id})){return c.moveToFirst()?c.getString(0):null;}}
    private static void audit(SQLiteDatabase db,String id,String action,String entity,long date,Map<String,Object> body){ContentValues v=new ContentValues();v.put("id",id);v.put("recorded_at",System.currentTimeMillis());v.put("occurred_at",date);v.put("action",action);v.put("entity_id",entity);v.put("payload",Json.write(body));db.insertOrThrow("audit",null,v);}
    public void request(Refunds.Request request){synchronized(store){SQLiteDatabase db=store.database();db.beginTransaction();try{String old=existing(db,"refund_requests",request.id()),json=Json.write(Refunds.requestMap(request));if(old!=null){if(!old.equals(json))Purchases.bad("Conflicting refund request ID.");db.setTransactionSuccessful();return;}ContentValues v=new ContentValues();v.put("sale_id",request.saleId());insert(db,"refund_requests",request.id(),Refunds.requestMap(request),v);view();audit(db,"refund-request-"+request.id(),"refund.request",request.saleId(),request.recordedAt(),Refunds.requestMap(request));db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    public void manual(Refunds.Request request,long fee){synchronized(store){SQLiteDatabase db=store.database();db.beginTransaction();try{request(request);var sale=store.snapshot().events().stream().filter(e->e.id().equals(request.saleId())).findFirst().orElseThrow();if(sale.payment().equals("cash")&&fee!=0)Purchases.bad("Cash refunds cannot have a card processing fee.");observe(new Refunds.Observation("manual-observation-"+request.id(),request.id(),"manual-"+request.id(),"succeeded",request.recordedAt(),request.recordedAt(),fee,""));db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    public void observe(Refunds.Observation incoming){synchronized(store){Refunds.Observation observation=incoming;SQLiteDatabase db=store.database();db.beginTransaction();try{String old=existing(db,"refund_observations",observation.id()),body=Json.write(Refunds.observationMap(observation));if(old!=null){if(!old.equals(body))Purchases.bad("Conflicting refund verification ID.");db.setTransactionSuccessful();return;}Refunds.Observation latest=null;try(Cursor previous=db.rawQuery("SELECT body FROM refund_observations WHERE request_id=? ORDER BY rowid DESC LIMIT 1",new String[]{observation.requestId()})){if(previous.moveToFirst())latest=Refunds.observation(Json.parse(previous.getString(0)));}if(latest!=null&&(observation.verifiedAt()<latest.verifiedAt()||observation.created()!=latest.created()||!observation.providerId().equals(latest.providerId())))Purchases.bad("Stale or conflicting refund response. Check status again.");if(latest!=null&&observation.fee()==null&&latest.fee()!=null)observation=new Refunds.Observation(observation.id(),observation.requestId(),observation.providerId(),observation.status(),observation.created(),observation.verifiedAt(),latest.fee(),observation.failureReason());body=Json.write(Refunds.observationMap(observation));if(latest!=null&&latest.providerId().equals(observation.providerId())&&latest.status().equals(observation.status())&&Objects.equals(latest.fee(),observation.fee())&&latest.failureReason().equals(observation.failureReason())){db.setTransactionSuccessful();return;}ContentValues fields=new ContentValues();fields.put("request_id",observation.requestId());insert(db,"refund_observations",observation.id(),Refunds.observationMap(observation),fields);view();audit(db,"refund-observation-"+observation.id(),"refund.status_verified",observation.requestId(),observation.verifiedAt(),Refunds.observationMap(observation));db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    public void verified(Ledger.Event sale,Map<String,Object> response){synchronized(store){SQLiteDatabase db=store.database();db.beginTransaction();try{var settings=new PaymentSettings(store.context());if(!FinanceBackup.bool(response,"live")||!settings.live()||!Purchases.str(response,"saleId").equals(sale.id())||!Purchases.str(response,"currency").equals("aud")||!Purchases.str(response,"paymentIntent").equals(intent(sale)))Purchases.bad("Refund response does not match the original live sale.");String id=Purchases.str(response,"requestId");var state=view();Refunds.Request request=null;for(var r:state.requests())if(r.id().equals(id))request=r;long amount=Purchases.num(response,"amount");if(request==null){request=new Refunds.Request(id,sale.id(),amount,System.currentTimeMillis(),"Imported from verified Stripe refund "+Purchases.str(response,"id"),true);ContentValues extra=new ContentValues();extra.put("sale_id",request.saleId());insert(db,"refund_requests",request.id(),Refunds.requestMap(request),extra);audit(db,"refund-request-"+request.id(),"refund.imported",request.saleId(),request.recordedAt(),Refunds.requestMap(request));}else if(!request.saleId().equals(sale.id())||request.amount()!=amount)Purchases.bad("Refund response amount/ID changed.");observe(new Refunds.Observation(Ledger.id(),id,Purchases.str(response,"id"),Purchases.str(response,"status"),Purchases.num(response,"created"),Purchases.num(response,"verifiedAt"),response.get("fee")==null?null:Purchases.num(response,"fee"),response.get("failureReason")==null?"":Purchases.str(response,"failureReason")));db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    public static String intent(Ledger.Event event){java.util.regex.Matcher match=java.util.regex.Pattern.compile("^Stripe (pi_[A-Za-z0-9]+) ·").matcher(event.note());return match.find()?match.group(1):null;}
    public void receive(String id,String requestId,long quantity,long now){synchronized(store){SQLiteDatabase db=store.database();db.beginTransaction();try{String old=existing(db,"refund_returns",id);if(old!=null){var r=Refunds.returned(Json.parse(old));if(!r.requestId().equals(requestId)||r.quantity()!=quantity||r.recordedAt()!=now)Purchases.bad("Conflicting returned-goods ID.");db.setTransactionSuccessful();return;}var state=view();Refunds.Request request=state.requests().stream().filter(r->r.id().equals(requestId)).findFirst().orElseThrow();var status=state.state().latest().get(requestId);if(status==null||!status.status().equals("succeeded"))Purchases.bad("Confirm/verify the refund before receiving returned stock.");Ledger.Event sale=store.snapshot().events().stream().filter(e->e.id().equals(request.saleId())).findFirst().orElseThrow();String product=Catalog.LEGACY;try(Cursor c=db.rawQuery("SELECT product_id FROM event_products WHERE event_id=?",new String[]{sale.id()})){if(c.moveToFirst()){product=c.getString(0);if(c.moveToNext())Purchases.bad("Mixed-flavour sale: enter separate reviewed stock adjustments.");}}var e=new Ledger.Event("refund-return-"+id,now,now,"restock",quantity,"none",0,0,0,"Physically received returned goods for sale "+sale.id(),null);CatalogStore.plan(db,e,Ledger.list(new Catalog.Allocation(product,quantity)));store.record(e);var received=new Refunds.Return(id,requestId,e.id(),quantity,now);ContentValues extra=new ContentValues();extra.put("request_id",requestId);extra.put("event_id",e.id());insert(db,"refund_returns",id,Refunds.returnMap(received),extra);view();audit(db,"refund-return-"+id,"refund.goods_received",requestId,now,Refunds.returnMap(received));db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    static void beforeUndo(SQLiteDatabase db,Ledger.Event event){if(!event.type().equals("undo"))return;try(Cursor c=db.rawQuery("SELECT 1 FROM refund_requests WHERE sale_id=?",new String[]{event.target()})){if(c.moveToFirst())Purchases.bad("This sale has refund history. Use refund records/status rather than undoing the original sale.");}}
    public Map<String,String> returnSources(){synchronized(store){var view=view();Map<String,Refunds.Request> requests=new HashMap<>();for(var r:view.requests())requests.put(r.id(),r);Map<String,String> result=new HashMap<>();for(var r:view.returns())result.put(r.eventId(),requests.get(r.requestId()).saleId());return result;}}
    public List<Finance.Row> financialRows(Map<String,Finance.Tax> taxes){synchronized(store){var view=view();Map<String,List<Catalog.Allocation>> allocations=new HashMap<>();for(Object value:Purchases.list(new CatalogStore(store).export().get("allocations"))){var m=Purchases.map(value);allocations.put(Purchases.str(m,"eventId"),Catalog.allocations(m.get("allocations")));}return Refunds.financialRows(view.requests(),view.observations(),store.snapshot().events(),taxes,allocations);}}
    void restore(Map<String,Object> data){if(data==null)return;SQLiteDatabase db=store.database();for(Object value:Purchases.list(data.get("requests")))restoreRow(db,"refund_requests",value,"sale_id","saleId",null,null);for(Object value:Purchases.list(data.get("observations")))restoreRow(db,"refund_observations",value,"request_id","requestId",null,null);for(Object value:Purchases.list(data.get("returns")))restoreRow(db,"refund_returns",value,"request_id","requestId","event_id","eventId");view();}
    private static void restoreRow(SQLiteDatabase db,String table,Object value,String column,String field,String secondColumn,String secondField){var m=Purchases.map(value);String id=Purchases.str(m,"id"),old=existing(db,table,id),body=Json.write(m);if(old!=null){if(!old.equals(body))Purchases.bad("Conflicting refund history. Restore cancelled.");return;}ContentValues extra=new ContentValues();extra.put(column,Purchases.str(m,field));if(secondColumn!=null)extra.put(secondColumn,Purchases.str(m,secondField));insert(db,table,id,m,extra);}
}
